using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
internal sealed partial class PadHop {
 readonly Dictionary<string,Button> bindingRows=new Dictionary<string,Button>();TextBlock outputSummary;CheckBox virtualOutputBox;bool loadingOutput;
 void BuildButtons(){var page=Get<StackPanel>("TouchPage");var card=Card(page,L.T("按位置设置按键"));var box=(UIElement)card.Parent;page.Children.Remove(box);page.Children.Insert(1,box);
 Hint(card,L.T("L 是左手，R 是右手。点一下按键卡片，直接编辑动作。"));
 virtualOutputBox=new CheckBox{Content=L.T("启用虚拟 Xbox 手柄（供游戏识别）")};card.Children.Add(virtualOutputBox);virtualOutputBox.Checked+=delegate{if(!loadingOutput){padBook.VirtualOutputEnabled=true;SyncButtons();UpdateFullStatus();}};virtualOutputBox.Unchecked+=delegate{if(!loadingOutput){padBook.VirtualOutputEnabled=false;SyncButtons();UpdateFullStatus();}};outputSummary=Hint(card,"");
 var tabs=new TabControl{Background=Brushes.Transparent,BorderThickness=new Thickness(0),Margin=new Thickness(0,6,0,0)};card.Children.Add(tabs);
 string[][] groups={new[]{"LB","RB","LT","RT","L3","R3"},new[]{"L4","R4","L5","R5","LG","RG"},new[]{"UP","Y","LEFT","X","RIGHT","B","DOWN","A","VIEW","MENU","QAM"}};
 string[] names={L.T("肩键、扳机与摇杆"),L.T("背面 · 背键与握把"),L.T("正面 · 方向与按钮")};for(int i=0;i<groups.Length;i++){var panel=new StackPanel{Margin=new Thickness(0,10,0,0)};tabs.Items.Add(new TabItem{Header=names[i],Content=panel});var heading=new Grid();heading.ColumnDefinitions.Add(new ColumnDefinition());heading.ColumnDefinitions.Add(new ColumnDefinition());for(int side=0;side<2;side++){var t=new TextBlock{Text=i<2?(side==0?L.T("左手侧"):L.T("右手侧")):(side==0?L.T("方向与视图"):L.T("正面与菜单")),Foreground=Brushes.LightBlue,Margin=new Thickness(8,4,8,8)};heading.Children.Add(t);Grid.SetColumn(t,side);}panel.Children.Add(heading);var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());panel.Children.Add(grid);for(int j=0;j<groups[i].Length;j++){if(j%2==0)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});string input=groups[i][j];var button=new Button{HorizontalContentAlignment=HorizontalAlignment.Stretch,Padding=new Thickness(14,10,14,10),Margin=new Thickness(0,0,j%2==0?8:0,8)};grid.Children.Add(button);Grid.SetRow(button,j/2);Grid.SetColumn(button,j%2);bindingRows[input]=button;button.Click+=delegate{EditBinding(input);};}}BuildStickEditor(tabs);tabs.SelectedIndex=1;SyncButtons();
 }
 BindingAction GetBinding(string input){if(input.StartsWith("LS_") || input.StartsWith("RS_"))return Stick(input.StartsWith("LS_")?0:1).Directions[input.Substring(3)];if(input=="LPRESS" || input=="RPRESS"){var p=input=="LPRESS"?padBook.Left:padBook.Right;return p.Click=="binding"?p.PressAction:p.Click=="none"?new BindingAction():new BindingAction{Kind="mouse",Chord=p.Click};}if(input.StartsWith("LP_") || input.StartsWith("RP_"))return (input.StartsWith("LP_")?padBook.Left:padBook.Right).Directions[input.Substring(3)];BindingAction a;padBook.EffectiveBindings().TryGetValue(input,out a);return a??new BindingAction();}
 void SyncButtons(){padBook.EnsureInputLayout();if(virtualOutputBox!=null){loadingOutput=true;virtualOutputBox.IsChecked=padBook.VirtualOutputEnabled;loadingOutput=false;}if(outputSummary!=null)outputSummary.Text=!padBook.VirtualOutputEnabled?L.T("手柄输出已关闭；键盘和鼠标映射仍可使用。"):padBook.NeedsVirtualGamepad?L.T("接管时供游戏识别为 Xbox 手柄；SC2 本身的设备类型不变。"):L.T("当前配置没有手柄输出，无需创建虚拟设备。");foreach(var row in bindingRows){var action=GetBinding(row.Key);var body=new StackPanel();body.Children.Add(new TextBlock{Text=InputCatalog.ButtonLabel(row.Key),FontWeight=FontWeights.SemiBold,FontSize=14});body.Children.Add(new TextBlock{Text=action.Kind=="none"?L.T("未设置"):action.ToString(),Foreground=Brushes.LightBlue,FontSize=12,Margin=new Thickness(0,5,0,0),TextTrimming=TextTrimming.CharacterEllipsis,TextWrapping=TextWrapping.NoWrap});row.Value.Content=body;}SyncPadMappings();SyncSticks();}
 void SetBinding(string input,BindingAction action){action.Validate();padBook.EnsureInputLayout();if(input.StartsWith("LS_") || input.StartsWith("RS_")){Stick(input.StartsWith("LS_")?0:1).Directions[input.Substring(3)]=action;}else if(input=="LPRESS" || input=="RPRESS"){var p=input=="LPRESS"?padBook.Left:padBook.Right;p.PressAction=action;p.Click="binding";clickBox.SelectedIndex=3;}else if(input.StartsWith("LP_") || input.StartsWith("RP_")){(input.StartsWith("LP_")?padBook.Left:padBook.Right).Directions[input.Substring(3)]=action;}else{if(padBook.Bindings==null){padBook.Bindings=new Dictionary<string,BindingAction>();if(padBook.KeyboardButton!="none")padBook.Bindings[padBook.KeyboardButton]=new BindingAction{Kind="osk"};}padBook.Bindings[input]=action;}SyncButtons();UpdateFullStatus();}
 void EditBinding(string input){Guard(delegate{CreateBindingDialog(input,GetBinding(input)).ShowDialog();});}
}
